// Paraphrase fixtures: whole trainee messages, as typed on a phone, and what the keyword grader must and must not read
// from them. Every grading change is tested against this list (Plan 2 Task 6), so it is the grader's safety net: a
// false Missed and a false credit both mis-teach the trainee.
//
// Each point that applies to some case has at least two positive lines (the notes' own wording and a shorter trainee
// wording), and each part at least one. `why` names the carry or rule a line pins. Lines run with `ctxAt(at, case)`:
// the run is on `at`, with every applicable point of the steps before it done.
export interface Paraphrase {
  at: string;          // the step id the run is on (ctx.current)
  line: string;        // a whole trainee message, as typed on a phone
  hits?: string[];     // 'step/point' or 'step/point.part' that must be read
  not?: string[];      // ones that must not be
  case?: string;       // default 'copd-amk-01'; trauma and conditional points use their case
  eta?: number;        // the run's ETA in minutes, default 6 (ctxAt)
  why?: string;        // the carry or rule the line pins
  /** The faults the line must not raise (final review I3): 'phrase', no point it reads lacks a key word or, at an oxygen,
   *  ECG or BP arm point, names no choice; 'wrong', each oxygen, ECG or BP arm it names is the case's own (Plan 3 T2: an
   *  arm the patient doesn't rule out); 'unclear', no sentence asks who it is for (R8). The test also sends the line
   *  through the run engine in Coached, at its step with every step before it done, and checks the line's flags. */
  noFault?: readonly Fault[];
}
export type Fault = 'phrase' | 'wrong' | 'unclear';
/** Every fault a fixture can rule out. */
const CLEAN: readonly Fault[] = ['phrase', 'wrong', 'unclear'];

const COPD = 'copd-amk-01';
const HYPO = 'hypo-hougang-01';
const CHEST = 'chestpain-bedok-01';
const CCF = 'ccf-jurong-01';
const ASTHMA = 'asthma-tampines-01';
const BLEED = 'bleed-woodlands-01';
const FALL = 'fall-yishun-01';
const RTA = 'rta-toapayoh-01';

/** 'step/point' plus 'step/point.part' for each part named. */
const parts = (key: string, ...ids: string[]) => [key, ...ids.map(id => `${key}.${id}`)];
/** The GCS point and each of its parts: what a line that is no GCS must not read. */
const GCS_KEYS = parts('vital-signs/gcs', 'eyes', 'verbal', 'motor', 'score');
const POINTS_1_TO_6 = ['point-1', 'point-2', 'point-3', 'point-4', 'point-5', 'point-6'];
const SRACIE = (age: string, ic: string, eta: string) =>
  `FMV 123, requesting for Alpha for unstable case of female / Chinese / ${age} / case of COPD due to low SpO2 and high RR / IC no. ${ic} / ETA ${eta} mins.`;
const SRACIE_PARTS = ['sex', 'race', 'age', 'case', 'two-signs', 'ic-no', 'eta'];
/** A COPD SRACIE as typed fast (final review I3): `sra` the sex, race and age run together as the trainee types them,
 *  `eta` the ETA. */
const SRACIE_PHONE = (sra: string, eta: string) =>
  `Requesting Alpha for unstable case of ${sra} / case of COPD due to low SpO2 and high RR / IC no. S54xxxxxA / ${eta}.`;
const SRACIE_CHEST = (ic: string) =>
  `FMV 123, requesting for Alpha for unstable case of male / Malay / 58 / case of AMI due to low SpO2 and high HR / IC no. ${ic} / ETA 6 mins.`;

